parameters.jsCode:
const raw =
  $input.first()?.json ?? {};

const start =
  $('Start Classificar')
    .first()
    ?.json ?? {};

const maxAttempts = 3;

let previousAttempt = 0;

try {
  const previousErrors =
    $('Normalizar Erro Groq')
      .all()
      .map(item => item.json)
      .filter(Boolean);

  const lastError =
    previousErrors.at(-1);

  previousAttempt =
    Number(
      lastError?.attempt ?? 0,
    );
} catch {
  previousAttempt = 0;
}

const attempt =
  previousAttempt + 1;

const promptUser =
  String(
    start.prompt_user ??
    start.MSG_Prompt_User ??
    '',
  ).trim();

const promptSystem =
  String(
    start.prompt_system ??
    start.MSG_Prompt_System ??
    '',
  ).trim();

const findApiRecord = (
  value,
  depth = 0,
) => {
  if (
    depth > 8 ||
    value === null ||
    value === undefined
  ) {
    return null;
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      const found =
        findApiRecord(
          item,
          depth + 1,
        );

      if (found) {
        return found;
      }
    }

    return null;
  }

  if (
    typeof value !== 'object'
  ) {
    return null;
  }

  if (
    'dsc_api_key' in value ||
    'dsc_plataforma' in value ||
    'dsc_status' in value
  ) {
    return value;
  }

  for (
    const child of Object.values(value)
  ) {
    const found =
      findApiRecord(
        child,
        depth + 1,
      );

    if (found) {
      return found;
    }
  }

  return null;
};

const api =
  findApiRecord(raw);

const errorResult = (
  code,
  category,
  diagnostic,
) => [
  {
    json: {
      _route: 'result',
      status: 'error',

      code,
      category,
      diagnostic,

      attempt,
      max_attempts: maxAttempts,

      prompt_user: promptUser,
      prompt_system: promptSystem,

      retry_with_another_api:
        false,
    },
  },
];

if (!promptUser) {
  return errorResult(
    'PROMPT_USER_REQUIRED',
    'validation',
    'O prompt_user não foi recebido.',
  );
}

if (!promptSystem) {
  return errorResult(
    'PROMPT_SYSTEM_REQUIRED',
    'validation',
    'O prompt_system não foi recebido.',
  );
}

if (
  !api ||
  api.id === null ||
  api.id === undefined ||
  !api.dsc_api_key
) {
  return errorResult(
    'NO_API_AVAILABLE',
    'capacity',
    String(
      api?.dsc_status ??
      'Nenhuma API Groq disponível.',
    ).slice(0, 500),
  );
}

const platform =
  String(
    api.dsc_plataforma ??
    '',
  )
    .trim()
    .toLowerCase();

if (platform !== 'groq') {
  return errorResult(
    'PLATFORM_MISMATCH',
    'configuration',
    'A API selecionada não pertence à plataforma Groq.',
  );
}

const model =
  String(
    api.dsc_url_servico ??
    '',
  )
    .trim()
    .replace(
      /^models\//,
      '',
    );

if (!model) {
  return errorResult(
    'MODEL_NOT_CONFIGURED',
    'configuration',
    'dsc_url_servico não contém um modelo Groq.',
  );
}

return [
  {
    json: {
      _route: 'request',
      status: 'ready',

      attempt,
      max_attempts: maxAttempts,

      api_id: Number(api.id),
      api_key: String(api.dsc_api_key),
      model,

      prompt_user: promptUser,
      prompt_system: promptSystem,

      request_body: {
        model,
        temperature: 0,
        reasoning_effort: 'low',
        stream: false,

        /*
         * 1024 reserva espaço para o raciocínio do modelo
         * sem truncar a resposta JSON.
         */
        max_completion_tokens: 1024,

        response_format: {
          type: 'json_object',
        },

        messages: [
          {
            role: 'system',
            content: promptSystem,
          },
          {
            role: 'user',
            content: promptUser,
          },
        ],
      },
    },
  },
];

parameters.query:
UPDATE Config_API_IA
SET
    dth_bloqueio_ate = DATE_ADD(
        DATE_SUB(
            UTC_TIMESTAMP(),
            INTERVAL 3 HOUR
        ),
        INTERVAL 60 MINUTE
    ),
    dsc_status = 'Congelada 60min: {{ $json.code }}'
WHERE id = {{
    Number.isInteger(Number($json.api_id))
        ? Number($json.api_id)
        : -1
}};

parameters.jsCode:
const input =
  $input.first()?.json ?? {};

const sanitize = value =>
  String(value ?? '')
    .replace(
      /Bearer\s+[A-Za-z0-9._~+/=-]+/gi,
      'Bearer [REDACTED]',
    )
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 500);

const parseJson = value => {
  if (
    typeof value !== 'string' ||
    !value.trim()
  ) {
    return null;
  }

  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
};

const extractEmbeddedError = value => {
  if (
    typeof value !== 'string'
  ) {
    return null;
  }

  const match =
    value.match(
      /^\s*(\d{3})\s*-\s*(\{[\s\S]*\})\s*$/,
    );

  if (!match) {
    return null;
  }

  const parsed =
    parseJson(match[2]);

  if (!parsed) {
    return null;
  }

  return {
    statusCode: Number(match[1]),
    body: parsed,
  };
};

const nestedError =
  input.error ??
  input.body?.error ??
  input;

const rawMessage =
  nestedError?.message ??
  input.message ??
  '';

const embedded =
  extractEmbeddedError(
    rawMessage,
  );

const body =
  embedded?.body ??
  input.body ??
  input;

const statusCode =
  Number(
    input.statusCode ??
    input.status_code ??
    input.httpStatus ??
    input.http_status ??
    input.error?.statusCode ??
    input.error?.status_code ??
    input.error?.httpCode ??
    input.error?.status ??
    embedded?.statusCode ??
    body?.statusCode ??
    0,
  );

const providerErrorCode =
  body?.error?.code ??
  input.error?.code ??
  nestedError?.code ??
  null;

const diagnostic =
  body?.error?.message ??
  nestedError?.message ??
  input.message ??
  'Erro não detalhado retornado pelo Groq.';

const apiId =
  $('Associar API a Tarefa')
    .item
    .json
    ?.api_id ??
  null;

let code =
  'GROQ_API_ERROR';

let category =
  'api';

let retryWithAnotherApi =
  false;

/*
 * Erros que justificam tentar outra API.
 */
if (
  providerErrorCode ===
    'model_permission_blocked_org'
) {
  code =
    'MODEL_PERMISSION_BLOCKED';

  category =
    'model_permission';

  retryWithAnotherApi =
    true;
} else if (
  statusCode === 401
) {
  code =
    'AUTHENTICATION_FAILED';

  category =
    'authentication';

  retryWithAnotherApi =
    true;
} else if (
  statusCode === 403
) {
  code =
    'AUTHORIZATION_FAILED';

  category =
    'authorization';

  retryWithAnotherApi =
    true;
} else if (
  statusCode === 429
) {
  code =
    'LIMIT_EXCEEDED';

  category =
    'quota_or_rate_limit';

  retryWithAnotherApi =
    true;
} else if (
  [
    408,
    425,
    500,
    502,
    503,
    504,
  ].includes(statusCode)
) {
  code =
    'UPSTREAM_UNAVAILABLE';

  category =
    'upstream';

  retryWithAnotherApi =
    true;
} else if (
  providerErrorCode ===
    'json_validate_failed'
) {
  /*
   * Falha no JSON gerado pelo modelo.
   * Não congela a API.
   */
  code =
    'INVALID_MODEL_JSON';

  category =
    'response';

  retryWithAnotherApi =
    false;
} else if (
  statusCode === 400
) {
  code =
    'INVALID_REQUEST';

  category =
    'request';

  retryWithAnotherApi =
    false;
}

return [
  {
    json: {
      _route: 'error',
      status: 'error',

      code,
      category,

      diagnostic:
        sanitize(
          embedded?.body?.error?.message ??
          diagnostic,
        ),

      provider_error_code:
        providerErrorCode,

      http_status:
        statusCode || null,

      retry_with_another_api:
        retryWithAnotherApi,

      block_seconds:
        retryWithAnotherApi
          ? 3600
          : null,

      api_id:
        apiId,
    },
  },
];

const input =
  $input.item.json ?? {};

const sanitize = value =>
  String(value ?? '')
    .replace(
      /Bearer\s+[A-Za-z0-9._~+/=-]+/gi,
      'Bearer [REDACTED]',
    )
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1000);

const code =
  input.code ??
  input.provider_error_code ??
  'GROQ_API_ERROR';

const category =
  input.category ??
  'api';

const diagnostic =
  sanitize(
    input.diagnostic ??
    'A chamada ao Groq não foi concluída.',
  );

return {
  json: {
    _route: 'error',
    status: 'error',

    code,
    category,
    diagnostic,

    provider_error_code:
      input.provider_error_code ??
      null,

    http_status:
      input.http_status ??
      null,

    retry_with_another_api:
      input.retry_with_another_api === true,

    block_seconds:
      input.block_seconds ??
      null,

    api_id:
      input.api_id ??
      null,

    erro: {
      codigo: code,
      categoria: category,
      diagnostico: diagnostic,
      http_status:
        input.http_status ??
        null,
      provider_error_code:
        input.provider_error_code ??
        null,
    },
  },
};

const response =
  $input.item.json ?? {};

const httpStatus = Number(
  response.statusCode ?? 0,
);

const body =
  response.body ?? response;

const choice =
  body?.choices?.[0];

const finishReason =
  choice?.finish_reason ?? null;

let rawContent =
  choice?.message?.content ??
  body?.text ??
  body?.content ??
  '';

if (
  rawContent &&
  typeof rawContent === 'object'
) {
  rawContent =
    JSON.stringify(rawContent);
}

const sanitize = value =>
  String(value ?? '')
    .replace(
      /Bearer\s+[A-Za-z0-9._~+/=-]+/gi,
      'Bearer [REDACTED]',
    )
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1000);

const errorResult = (
  code,
  category,
  diagnostic,
  details = [],
) => ({
  json: {
    _route: 'result',
    status: 'error',

    code,
    category,
    diagnostic,
    details,

    http_status:
      httpStatus || null,

    finish_reason:
      finishReason,

    api_id:
      $('Associar API a Tarefa')
        .item
        .json
        ?.api_id ??
      null,
  },
});

if (
  httpStatus < 200 ||
  httpStatus >= 300
) {
  return errorResult(
    'GROQ_API_ERROR',
    'api',
    sanitize(
      body?.error?.message ??
      body?.message ??
      'A API Groq retornou erro.',
    ),
  );
}

if (
  finishReason !== 'stop' &&
  finishReason !== 'length'
) {
  return errorResult(
    'INCOMPLETE_CLASSIFICATION',
    'response',
    'O modelo encerrou a resposta sem concluir a classificação.',
  );
}

const cleanJsonText = value =>
  String(value ?? '')
    .replace(
      /```json\s*/gi,
      '',
    )
    .replace(
      /```\s*$/g,
      '',
    )
    .replace(
      /[\u200b-\u200d\ufeff]/g,
      '',
    )
    .trim();

const jsonText =
  cleanJsonText(rawContent);

if (!jsonText) {
  return errorResult(
    'EMPTY_CLASSIFICATION',
    'response',
    'A resposta do Groq não contém JSON.',
  );
}

let data;

try {
  data =
    JSON.parse(jsonText);
} catch {
  return errorResult(
    'INVALID_CLASSIFICATION_JSON',
    'response',
    'A resposta do Groq não é um JSON válido.',
    [
      {
        field: 'response',
        value: sanitize(jsonText),
      },
    ],
  );
}

if (
  !data ||
  typeof data !== 'object' ||
  Array.isArray(data)
) {
  return errorResult(
    'INVALID_CLASSIFICATION_OBJECT',
    'response',
    'A classificação deve ser um objeto JSON.',
  );
}

const toPositiveInteger = value => {
  const number =
    Number(value);

  return Number.isInteger(number) &&
    number > 0
    ? number
    : null;
};

const toIdArray = value => {
  const values =
    Array.isArray(value)
      ? value
      : value === null ||
        value === undefined ||
        value === ''
        ? []
        : [value];

  return values
    .map(toPositiveInteger)
    .filter(
      value => value !== null,
    );
};

const categoriaId =
  toPositiveInteger(
    data.categoria_id ??
    data.categoria ??
    (
      Array.isArray(
        data.categories,
      )
        ? data.categories[0]
        : data.categories
    ),
  );

const tagsIds =
  toIdArray(
    data.tags_ids ??
    data.tags,
  );

const llmAutorId =
  toPositiveInteger(
    data.autor_id ??
    data.user_id ??
    data.autoria ??
    (
      Array.isArray(data.autor)
        ? data.autor[0]
        : data.autor
    ),
  );

const details = [];

if (
  categoriaId === null
) {
  details.push({
    field: 'categoria_id',
    code: 'INVALID_CATEGORY_ID',
    message:
      'categoria_id deve ser um inteiro positivo.',
  });
}

if (
  tagsIds.length < 1 ||
  tagsIds.length > 3
) {
  details.push({
    field: 'tags_ids',
    code: 'INVALID_TAG_COUNT',
    message:
      'tags_ids deve conter de 1 a 3 IDs.',
  });
}

if (
  new Set(tagsIds).size !==
  tagsIds.length
) {
  details.push({
    field: 'tags_ids',
    code: 'DUPLICATE_TAGS',
    message:
      'tags_ids não pode conter IDs repetidos.',
  });
}

if (
  categoriaId !== null &&
  tagsIds.includes(categoriaId)
) {
  details.push({
    field: 'tags_ids',
    code: 'CATEGORY_TAG_DUPLICATION',
    message:
      'O ID da categoria não deve ser repetido como tag.',
  });
}

if (details.length > 0) {
  return errorResult(
    'INVALID_CLASSIFICATION',
    'validation',
    'A classificação retornada não possui estrutura válida.',
    details,
  );
}

let start = {};

try {
  start =
    $('Start Classificar')
      .first()
      .json ?? {};
} catch {
  start = {};
}

const promptSystem =
  String(
    start.prompt_system ??
    start.MSG_Prompt_System ??
    '',
  );

/*
 * Captura somente os números da seção AUTOR.
 *
 * Exemplos aceitos:
 *
 * CATÁLOGO AUTOR:
 * 1, 2, 13
 *
 * #5 - AUTOR:
 * 1, 2, 13
 *
 * A captura termina antes de:
 * - outro cabeçalho numerado;
 * - VALIDAÇÃO;
 * - FORMATO;
 * - SAÍDA.
 */
const authorSectionMatch =
  promptSystem.match(
    /(?:CAT[ÁA]LOGO\s+AUTOR|#\s*\d+\s*[-–]\s*AUTOR)[^\n]*(?:\n|:)([\s\S]*?)(?=\n\s*(?:#\s*\d+|VALIDA[ÇC][ÃA]O|VALIDAÇÃO|FORMATO|SA[IÍ]DA)|$)/i,
  );

const authorBlock =
  authorSectionMatch?.[1] ??
  '';

const authorIds = [
  ...authorBlock.matchAll(
    /\b\d+\b/g,
  ),
]
  .map(
    match => Number(match[0]),
  )
  .filter(
    id =>
      Number.isInteger(id) &&
      id > 0,
  )
  .filter(
    (id, index, list) =>
      list.indexOf(id) === index,
  );

if (
  authorIds.length === 0
) {
  return errorResult(
    'AUTHOR_LIST_NOT_FOUND',
    'prompt',
    'A lista de autores não foi encontrada no prompt_system.',
  );
}

/*
 * Seleção final do autor pelo próprio fluxo.
 * Nenhum ID de autor fica fixo no código.
 */
const selectedAuthor =
  authorIds[
    Math.floor(
      Math.random() *
      authorIds.length,
    )
  ];

return {
  json: {
    _route: 'result',
    status: 'success',
    classification_valid: true,

    autor: [selectedAuthor],
    categories: [categoriaId],
    tags: tagsIds,

    autor_id: selectedAuthor,
    categoria_id: categoriaId,
    tags_ids: tagsIds,

    llm_autor_id:
      llmAutorId,

    author_selection:
      'parent_prompt_random',

    author_catalog_size:
      authorIds.length,

    usage:
      body?.usage ??
      null,

    model:
      body?.model ??
      null,

    api_id:
      $('Associar API a Tarefa')
        .item
        .json
        ?.api_id ??
      null,

    http_status:
      httpStatus,

    finish_reason:
      finishReason,
  },
};

const normalizedError =
  $input.item.json ?? {};

const maxAttempts = 3;

const errorResult = (
  code,
  diagnostic,
  attempt = null,
) => ({
  json: {
    _route: 'error',
    status: 'error',

    code,
    category: 'response',
    diagnostic,

    provider_error_code:
      normalizedError.provider_error_code ??
      null,

    http_status:
      normalizedError.http_status ??
      null,

    api_id:
      normalizedError.api_id ??
      null,

    attempt,
    max_attempts: maxAttempts,

    retry_with_another_api: false,
    block_seconds: null,
  },
});

let failedRequest = null;

try {
  failedRequest =
    $('HTTP Groq Chat Completions')
      .item
      .json;
} catch {
  failedRequest = null;
}

if (
  !failedRequest ||
  typeof failedRequest !== 'object'
) {
  return errorResult(
    'RETRY_CONTEXT_NOT_FOUND',
    'Não foi possível recuperar a requisição que falhou.',
  );
}

const currentAttempt =
  Number(failedRequest.attempt);

if (
  !Number.isInteger(currentAttempt) ||
  currentAttempt < 1
) {
  return errorResult(
    'INVALID_RETRY_ATTEMPT',
    'A tentativa atual não foi encontrada ou é inválida.',
  );
}

if (
  currentAttempt >= maxAttempts
) {
  return errorResult(
    'RETRY_EXHAUSTED',
    'O Groq não produziu uma classificação válida após três tentativas.',
    currentAttempt,
  );
}

if (
  !failedRequest.api_key ||
  !failedRequest.request_body ||
  typeof failedRequest.request_body !== 'object'
) {
  return errorResult(
    'RETRY_REQUEST_INCOMPLETE',
    'A requisição original não possui os dados necessários para repetir a chamada.',
    currentAttempt,
  );
}

const requestBody = {
  ...failedRequest.request_body,
};

/*
 * A resposta truncada recebe mais espaço de conclusão
 * em cada nova tentativa. O JSON mode permanece ativo
 * para reduzir respostas fora do formato.
 */
const retryMaxCompletionTokens =
  Math.min(
    4096,
    Math.max(
      2048,
      (currentAttempt + 1) * 1024,
    ),
  );

requestBody.max_completion_tokens =
  retryMaxCompletionTokens;

requestBody.response_format = {
  type: 'json_object',
};

return {
  json: {
    _route: 'retry_json',
    status: 'ready',

    attempt:
      currentAttempt + 1,

    max_attempts:
      maxAttempts,

    api_id:
      failedRequest.api_id ??
      normalizedError.api_id ??
      null,

    api_key:
      failedRequest.api_key,

    model:
      failedRequest.model ??
      requestBody.model ??
      null,

    prompt_user:
      failedRequest.prompt_user ??
      null,

    prompt_system:
      failedRequest.prompt_system ??
      null,

    request_body:
      requestBody,
  },
};
